/* ===== parallax: mouse on desktop, tilt on phones ===== */
let tx = 0,
    ty = 0,
    cx = 0,
    cy = 0;
const clamp = (v) => Math.max(-1, Math.min(1, v));
addEventListener('pointermove', (e) => {
    if (e.pointerType === 'mouse') {
        tx = clamp((e.clientX / innerWidth - .5) * 2);
        ty = clamp((e.clientY / innerHeight - .5) * 2);
    }
});

function tilt() {
    addEventListener('deviceorientation', (e) => {
        if (e.gamma == null) return;
        tx = clamp(e.gamma / 22);
        ty = clamp(((e.beta || 50) - 50) / 22);
    });
}
(function loop() {
    cx += (tx - cx) * .07;
    cy += (ty - cy) * .07;
    poster.style.setProperty('--px', cx.toFixed(3));
    poster.style.setProperty('--py', cy.toFixed(3));
    requestAnimationFrame(loop);
})();
if (!(window.DeviceOrientationEvent && DeviceOrientationEvent.requestPermission)) tilt();

