const curtainEl = $('#curtain');
const curtainPanels = curtainEl.querySelectorAll('.cr');
const sealEl = $('#cr-seal'),
    lightEl = curtainEl.querySelector('.cr-light');
$('#cr-names').textContent = CONFIG.name1 + ' & ' + CONFIG.name2;
const reduceMotion = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;

function curtainReveal(delay, onStart) {
    [sealEl, lightEl, curtainEl, ...curtainPanels].forEach((e) => e.getAnimations().forEach((a) => a.cancel()));
    curtainEl.hidden = false;
    const lead = reduceMotion ? 150 : 800,
        dur = reduceMotion ? 1600 : 3600;
    setTimeout(() => {
        sealEl.animate([{
            opacity: 1,
            transform: 'scale(1)'
        }, {
            opacity: 0,
            transform: 'scale(1.35)'
        }], {
            duration: lead,
            easing: 'ease-in',
            fill: 'forwards'
        });
        setTimeout(() => {
            curtainPanels.forEach((p, i) => {
                const s = i ? -1 : 1;
                p.animate([{
                    transform: 'scaleX(1) skewX(0deg)'
                }, {
                    offset: .55,
                    transform: 'scaleX(.42) skewX(' + (2.2 * s) + 'deg)'
                }, {
                    transform: 'scaleX(.12) skewX(0deg)'
                }], {
                    duration: dur,
                    easing: 'cubic-bezier(.55,0,.2,1)',
                    fill: 'forwards'
                });
            });
            lightEl.animate([{
                opacity: 0
            }, {
                offset: .35,
                opacity: 1
            }, {
                offset: .8,
                opacity: .8
            }, {
                opacity: 0
            }], {
                duration: dur + 600,
                fill: 'forwards'
            });
            setTimeout(onStart, 1000);
            setTimeout(() => {
                curtainEl.animate([{
                    opacity: 1
                }, {
                    opacity: 0
                }], {
                    duration: 600,
                    fill: 'forwards'
                });
            }, dur + 100);
            setTimeout(() => {
                curtainEl.hidden = true;
                [sealEl, lightEl, curtainEl, ...curtainPanels].forEach((e) => e.getAnimations().forEach((a) => a.cancel()));
            }, dur + 800);
        }, lead - 250);
    }, delay + (reduceMotion ? 0 : 900));
}

/* show the distance pill only after every other element of the card has finished animating */
function schedulePill() {
    const pill = $('#distpill');
    pill.classList.remove('show');
    if (GUEST.km == null) return;
    setTimeout(() => {
        const pending = poster.getAnimations({
            subtree: true
        }).filter((a) => a.effect && a.effect.getComputedTiming().iterations !== Infinity && a.playState !== 'finished' && !pill.contains(a.effect.target)).map((a) => a.finished.catch(() => {}));
        Promise.race([Promise.all(pending), new Promise((r) => setTimeout(r, 3000))]).then(() => setTimeout(() => pill.classList.add('show'), 400));
    }, 600);
}

function play() {
    poster.classList.remove('on');
    curtainReveal(250, () => {
        poster.classList.add('on');
        startFX();
        rain(30);
        schedulePill();
    });
}
