/* ---- location: same rules as the Shanvika page ----
   - location is required to open the invitation (no skip)
   - browser without geolocation -> message, button disabled
   - permission already granted -> position is fetched automatically
   - permission denied / failed -> "Try Again"
   - fresh position every time (maximumAge 0, 10 s timeout), saved in localStorage
   - coordinates + name are sent to the Google Sheet only when lat/lng exist */
const geoData = {
    lat: '',
    lng: ''
};
const locBtn = $('#g-loc'),
    locStatus = $('#g-status');
const BLOCKED = 'Location is blocked for this site. Allow it in your browser settings, then tap Try Again.';

const skipBtn = $('#g-skip');

function showLocationHelp(msg) {
    locStatus.textContent = msg || 'Tap Try Again.';
    locBtn.disabled = false;
    locBtn.textContent = 'TRY AGAIN';
    skipBtn.hidden = false;
}
skipBtn.addEventListener('click', () => {
    sheetRequest({
        name: GUEST.name,
        event: 'no_location',
        allowNoLoc: true
    });
    $('#g-hello2').textContent = 'Thank you, ' + GUEST.name + '!';
    $('#g-result').textContent = 'We look forward to celebrating with you.';
    setMap();
    showStep('s-done');
});
async function getLocationPermissionState() {
    if (!navigator.geolocation) return 'unsupported';
    if (!navigator.permissions || !navigator.permissions.query) return 'prompt';
    try {
        return (await navigator.permissions.query({
            name: 'geolocation'
        })).state;
    } catch (e) {
        return 'prompt';
    }
}

function sheetRequest(params) {
    const hasPos = geoData.lat && geoData.lng;
    if (!CONFIG.sheetUrl || (!hasPos && !params.allowNoLoc)) return;
    const all = Object.assign({
        page: CONFIG.sheetPage
    }, hasPos ? {
        lat: geoData.lat,
        lng: geoData.lng
    } : {}, params);
    delete all.allowNoLoc;
    const url = CONFIG.sheetUrl + '?' + Object.keys(all).map((k) => encodeURIComponent(k) + '=' + encodeURIComponent(all[k])).join('&');
    fetch(url, {
        mode: 'no-cors'
    }).catch((err) => console.warn('Sheet request failed:', err));
}
/* Same as Shanvika's sendLocationToSheet: page, lat, lng, event (plus name + straight-line distance) */
function sendToSheet(eventType) {
    sheetRequest({
        name: GUEST.name,
        distance: haversine(geoData.lat, geoData.lng, CONFIG.venueLat, CONFIG.venueLng).toFixed(1),
        event: eventType
    });
}

function requestUserLocation() {
    return new Promise((resolve, reject) => {
        navigator.geolocation.getCurrentPosition((pos) => {
            geoData.lat = pos.coords.latitude;
            geoData.lng = pos.coords.longitude;
            try {
                localStorage.setItem('wedding_lat', String(geoData.lat));
                localStorage.setItem('wedding_lng', String(geoData.lng));
                localStorage.setItem('wedding_location_time', new Date().toISOString());
            } catch (e) {}
            sendToSheet('page_open');
            resolve();
        }, (err) => {
            let m = 'Tap Try Again.';
            if (err && err.code === 1) m = window.isSecureContext === false ? 'Location needs a secure (https) page. Please open the invitation link in your browser.' : BLOCKED;
            else if (err && err.code === 2) m = 'Your location is unavailable right now. Tap Try Again.';
            else if (err && err.code === 3) m = 'Finding your location took too long. Tap Try Again.';
            else if (err && err.message) m = err.message;
            reject(new Error(m));
        }, {
            enableHighAccuracy: false,
            timeout: 10000,
            maximumAge: 0
        });
    });
}
const toRad = (d) => d * Math.PI / 180;

function haversine(a, b, c, d) {
    const dl = toRad(c - a),
        dn = toRad(d - b),
        x = Math.sin(dl / 2) ** 2 + Math.cos(toRad(a)) * Math.cos(toRad(c)) * Math.sin(dn / 2) ** 2;
    return 12742 * Math.asin(Math.sqrt(x));
}
const fmtKm = (km) => km < 1 ? Math.round(km * 1000) + ' m' : (km < 10 ? km.toFixed(1) : Math.round(km).toLocaleString('en-IN')) + ' km';
const fmtDur = (m) => m < 60 ? m + ' min' : Math.floor(m / 60) + ' h' + (m % 60 ? ' ' + (m % 60) + ' min' : '');
async function route(lat, lng) {
    const crow = haversine(lat, lng, CONFIG.venueLat, CONFIG.venueLng);
    try {
        const ctl = new AbortController(),
            to = setTimeout(() => ctl.abort(), 4500);
        const r = await fetch('https://router.project-osrm.org/route/v1/driving/' + lng + ',' + lat + ';' + CONFIG.venueLng + ',' + CONFIG.venueLat + '?overview=false', {
            signal: ctl.signal
        });
        clearTimeout(to);
        const j = await r.json();
        if (j.code === 'Ok' && j.routes && j.routes[0]) return {
            km: j.routes[0].distance / 1000,
            mins: Math.round(j.routes[0].duration / 60),
            road: true
        };
    } catch (e) {}
    return {
        km: crow,
        mins: null,
        road: false
    };
}

function finishGate() {
    const line = GUEST.road ? fmtKm(GUEST.km) + ' from you by road' + (GUEST.mins ? ' · about ' + fmtDur(GUEST.mins) : '') : 'about ' + fmtKm(GUEST.km) + ' from you (straight line)';
    $('#g-hello2').textContent = 'Thank you, ' + GUEST.name + '!';
    const gr = $('#g-result');
    gr.textContent = '';
    const pi = new Image();
    pi.src = 'assets/pin.png';
    pi.className = 'pin';
    pi.alt = '';
    gr.append(pi, ' The venue is ' + line);
    setMap();
    showStep('s-done');
}
async function locationSuccess() {
    locStatus.textContent = 'Calculating distance…';
    GUEST.lat = geoData.lat;
    GUEST.lng = geoData.lng;
    Object.assign(GUEST, await route(geoData.lat, geoData.lng));
    if (CONFIG.sheetSendNameAsWish) sheetRequest({
        name: GUEST.name,
        message: 'Opened the invitation - ' + (GUEST.road ? fmtKm(GUEST.km) + ' by road' : 'about ' + fmtKm(GUEST.km) + ' straight line') + ' from the venue',
        event: 'wish_submit'
    });
    finishGate();
}
async function startLocationFlow() {
    locStatus.textContent = '';
    locBtn.textContent = '📍 ALLOW LOCATION';
    locBtn.disabled = true;
    if (!navigator.geolocation) {
        locStatus.textContent = '❌ This browser does not support location access.';
        skipBtn.hidden = false;
        return;
    }
    const state = await getLocationPermissionState();
    if (state === 'granted') {
        locStatus.textContent = 'Finding your location…';
        try {
            await requestUserLocation();
            await locationSuccess();
        } catch (err) {
            console.warn('Refresh failed:', err);
            showLocationHelp('Could not be refreshed. Check your browser/site and tap Try Again.');
        }
        return;
    }
    if (state === 'denied') {
        showLocationHelp(BLOCKED);
        return;
    }
    locBtn.disabled = false;
}
locBtn.addEventListener('click', async () => {
    locBtn.disabled = true;
    if ((await getLocationPermissionState()) === 'denied') {
        showLocationHelp(BLOCKED);
        return;
    }
    locStatus.textContent = 'Finding your location…';
    try {
        await requestUserLocation();
        await locationSuccess();
    } catch (err) {
        console.warn('Request failed:', err);
        showLocationHelp('❌ ' + (err.message || 'Access failed.'));
    }
});

function enter() {
    unlockAudio();
    $('#intro').classList.add('out');
    document.body.classList.remove('locked');
    chime(660, 2.6, .2);
    setTimeout(() => chime(990, 2.2, .12), 200);
    setTimeout(() => chime(1320, 1.8, .08), 420);
    const bb = $('.intro-card').getBoundingClientRect(),
        fl = $('#flash');
    fl.style.left = (bb.left + bb.width / 2) + 'px';
    fl.style.top = (bb.top + bb.height * .75) + 'px';
    fl.classList.add('go');
    if (GUEST.km != null) {
        const dt = $('#distText');
        dt.textContent = '';
        const pi = new Image();
        pi.src = 'assets/pin.png';
        pi.className = 'pin';
        pi.alt = '';
        dt.append(pi, ' ' + (GUEST.road ? '' : '≈ ') + fmtKm(GUEST.km) + ' from you' + (GUEST.mins ? ' · ' + fmtDur(GUEST.mins) : ''));
    }
    poster.dataset.opening = '1';
    startMusic();
    curtainReveal(1700, () => {
        poster.classList.add('on');
        startFX();
        rain(36);
        schedulePill();
    });
    setTimeout(() => $('#intro').remove(), 1500);
}
$('#open').addEventListener('click', enter);

