const bgm = new Audio('assets/music.mp3');
bgm.loop = true;
bgm.volume = .45;
bgm.preload = 'none';

function startMusic() {
    if (soundOn && (poster.classList.contains('on') || poster.dataset.opening)) bgm.play().catch(() => {});
}
document.addEventListener('visibilitychange', () => {
    if (document.hidden) bgm.pause();
    else startMusic();
});

